      es: ["Parque natural regional", "Agricultura tradicional", "Rutas de senderismo", "Biodiversidad"],
      pt: ["Parque natural regional", "Agricultura tradicional", "Trilhos de caminhada", "Biodiversidade"],
      fr: ["Parc naturel régional", "Agriculture traditionnelle", "Sentiers de randonnée", "Biodiversité"],
